import{_ as d,C as l,o as c,c as p,a2 as i,E as a,w as n,j as t,a as r}from"./chunks/framework.Dh-DajNq.js";const C=JSON.parse('{"title":"Chapter 22: The Anatomy of Large Data: Chunks & Checksums","description":"","frontmatter":{},"headers":[],"relativePath":"book/part-04-media-search-edge/chapter-22-anatomy-of-large-data-chunks-checksums.md","filePath":"book/part-04-media-search-edge/chapter-22-anatomy-of-large-data-chunks-checksums.md"}'),h={name:"book/part-04-media-search-edge/chapter-22-anatomy-of-large-data-chunks-checksums.md"};function u(m,e,g,A,b,f){const s=l("Mermaid"),o=l("ClientOnly");return c(),p("div",null,[e[0]||(e[0]=i('<h1 id="chapter-22-the-anatomy-of-large-data-chunks-checksums" tabindex="-1">Chapter 22: The Anatomy of Large Data: Chunks &amp; Checksums <a class="header-anchor" href="#chapter-22-the-anatomy-of-large-data-chunks-checksums" aria-label="Permalink to &quot;Chapter 22: The Anatomy of Large Data: Chunks &amp; Checksums&quot;">​</a></h1><blockquote><p><em>&quot;Never stream gigabytes through application memory. Let storage engines store, let compute engines compute, and verify every byte with cryptographic checksums.&quot;</em></p></blockquote><hr><h2 id="_1-the-mystery-the-98-upload-heartbreak" tabindex="-1">1. The Mystery: The 98% Upload Heartbreak <a class="header-anchor" href="#_1-the-mystery-the-98-upload-heartbreak" aria-label="Permalink to &quot;1. The Mystery: The 98% Upload Heartbreak&quot;">​</a></h2><p>A healthcare platform enabled hospitals to upload high-resolution 3GB DICOM MRI scans.</p><p>A rural clinic with a 10 Mbps satellite link spent 45 minutes uploading a critical patient scan. At <strong>2.94GB (98% progress)</strong>, a momentary atmospheric storm caused a 2-second packet drop.</p><p>The browser socket disconnected. The application server threw an <code>ECONNRESET</code> exception, flushed its memory buffer, and closed the connection.</p><p>The doctor’s screen flashed: <code>&quot;Upload Failed. Please try again.&quot;</code></p>',8)),a(o,null,{default:n(()=>[a(s,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Clinic%20as%20Rural%20Hospital%0A%20%20%20%20participant%20App%20as%20Backend%20Web%20Server%20(RAM)%0A%20%20%20%20participant%20Disk%20as%20Persistent%20Disk%0A%0A%20%20%20%20Clinic-%3E%3EApp%3A%201.%20Stream%203GB%20MRI%20scan%20via%20POST%20%2Fupload%0A%20%20%20%20Note%20over%20App%3A%20Server%20buffers%20upload%20stream%20into%203GB%20RAM%20buffer!%0A%20%20%20%20Note%20over%20Clinic%3A%2045%20minutes%20elapse...%202.94GB%20transferred%20(98%25)%0A%20%20%20%20Note%20over%20Clinic%3A%202-second%20satellite%20packet%20drop%20(Socket%20Reset)!%0A%20%20%20%20App--xClinic%3A%20Connection%20Reset%20(ECONNRESET)%0A%20%20%20%20Note%20over%20App%3A%20App%20memory%20buffer%20discarded!%3Cbr%2F%3EZero%20bytes%20saved%20to%20disk.%0A%20%20%20%20Clinic-%3E%3EClinic%3A%20Doctor%20forced%20to%20restart%203GB%20upload%20from%20Byte%200!%0A"})]),_:1}),e[1]||(e[1]=t("p",null,[r("Worse, twenty clinics uploading scans simultaneously consumed "),t("strong",null,"60GB of application RAM"),r(", triggering the Linux Out-Of-Memory (OOM) killer and crashing the entire hospital scheduling portal.")],-1)),e[2]||(e[2]=t("p",null,[r("The architecture violated two laws of scale: "),t("strong",null,"it piped heavy binary blobs through application compute, and treated a multi-gigabyte upload as an atomic, all-or-nothing operation.")],-1)),e[3]||(e[3]=t("hr",null,null,-1)),e[4]||(e[4]=t("h2",{id:"_2-multipart-uploads-chunked-checksums",tabindex:"-1"},[r("2. Multipart Uploads & Chunked Checksums "),t("a",{class:"header-anchor",href:"#_2-multipart-uploads-chunked-checksums","aria-label":'Permalink to "2. Multipart Uploads & Chunked Checksums"'},"​")],-1)),e[5]||(e[5]=t("p",null,[r("A 3GB file must never travel as a single HTTP stream. It must be sliced into independent "),t("strong",null,"Chunks"),r(":")],-1)),a(o,null,{default:n(()=>[a(s,{code:"flowchart%20TD%0A%20%20%20%20File%5B%223GB%20MRI%20Scan%20(Client-Side%20File%20API)%22%5D%20--%3E%20Slicer%5B%22Slice%20into%20600%20Chunks%20of%205MB%20Each%22%5D%0A%20%20%20%20%0A%20%20%20%20subgraph%20ParallelUpload%20%5B%22Concurrent%20Resumable%20Multipart%20Upload%22%5D%0A%20%20%20%20%20%20%20%20Slicer%20--%3E%20C1%5B%22Chunk%201%20(5MB)%20%2B%20MD5%20Checksum%22%5D%20--%3E%20S3%5B%22Direct%20to%20S3%20%2F%20Object%20Store%22%5D%0A%20%20%20%20%20%20%20%20Slicer%20--%3E%20C2%5B%22Chunk%202%20(5MB)%20%2B%20MD5%20Checksum%22%5D%20--%3E%20S3%0A%20%20%20%20%20%20%20%20Slicer%20--%3E%20C491%5B%22Chunk%20491%20(5MB)%20(FAILS%20ON%20SATELLITE%20DROP)%22%5D%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20C491%20--%3E%20Retry%5B%22Retry%20ONLY%20Chunk%20491!%5Cn(Re-uploads%205MB%20in%204%20seconds%20instead%20of%203GB)%22%5D%0A%20%20%20%20Retry%20--%3E%20S3%0A%20%20%20%20S3%20--%3E%20Assembly%5B%22S3%20Assembles%20Complete%203GB%20Object%20in%20Cloud%22%5D%0A%0A%20%20%20%20classDef%20default%20fill%3A%231e293b%2Cstroke%3A%233b82f6%2Cstroke-width%3A1.5px%2Ccolor%3A%23f8fafc%3B%0A%20%20%20%20classDef%20alert%20fill%3A%237c2d12%2Cstroke%3A%23ef4444%2Cstroke-width%3A2px%2Ccolor%3A%23fecaca%3B%0A%20%20%20%20class%20C491%20alert%3B%0A"})]),_:1}),e[6]||(e[6]=i('<h3 id="the-resumability-invariants" tabindex="-1">The Resumability Invariants: <a class="header-anchor" href="#the-resumability-invariants" aria-label="Permalink to &quot;The Resumability Invariants:&quot;">​</a></h3><ol><li><strong>Parallel Uploads</strong>: The browser uploads 4 chunks concurrently across separate HTTP connections, saturating available bandwidth.</li><li><strong>Granular Retries</strong>: If network drops at 98%, only the currently active 5MB chunk fails. The preceding 599 chunks are already safely stored.</li><li><strong>End-to-End Checksums</strong>: Each chunk carries an <code>Content-MD5</code> header. The storage engine validates that received bits match transmitted bits before confirming receipt.</li></ol><hr><h2 id="_3-bypassing-application-compute-presigned-urls" tabindex="-1">3. Bypassing Application Compute: Presigned URLs <a class="header-anchor" href="#_3-bypassing-application-compute-presigned-urls" aria-label="Permalink to &quot;3. Bypassing Application Compute: Presigned URLs&quot;">​</a></h2><p>Application servers should never act as high-bandwidth network proxies for large binary payloads:</p>',5)),a(o,null,{default:n(()=>[a(s,{code:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Client%20as%20Client%20Browser%0A%20%20%20%20participant%20API%20as%20App%20Backend%20(Auth%20%26%20Metadata)%0A%20%20%20%20participant%20S3%20as%20Object%20Storage%20(AWS%20S3%20%2F%20GCS)%0A%0A%20%20%20%20Client-%3E%3EAPI%3A%201.%20POST%20%2Fscans%2Finitiate%20(file_name%2C%203GB%2C%20600%20parts)%0A%20%20%20%20Note%20over%20API%3A%20Verifies%20user%20permissions%20%26%20quota%0A%20%20%20%20API-%3E%3ES3%3A%202.%20Request%20600%20Presigned%20S3%20Part%20URLs%0A%20%20%20%20S3--%3E%3EAPI%3A%20Cryptographically%20signed%20URLs%20(15-min%20expiry)%0A%20%20%20%20API--%3E%3EClient%3A%20Return%20Presigned%20URLs%0A%20%20%20%20%0A%20%20%20%20loop%20For%20each%205MB%20Chunk%0A%20%20%20%20%20%20%20%20Client-%3E%3ES3%3A%203.%20PUT%20chunk%20direct%20to%20S3%20Presigned%20URL%20(Zero%20App%20CPU!)%0A%20%20%20%20%20%20%20%20S3--%3E%3EClient%3A%20HTTP%20200%20OK%20(ETag%3A%20MD5%20Hash)%0A%20%20%20%20end%0A%20%20%20%20%0A%20%20%20%20Client-%3E%3EAPI%3A%204.%20POST%20%2Fscans%2Fcomplete%20(ETag%20List)%0A%20%20%20%20API-%3E%3ES3%3A%205.%20CompleteMultipartUpload%20-%3E%20File%20Sealed!%0A"})]),_:1}),e[7]||(e[7]=i('<p>The application server processes only lightweight JSON metadata (milliseconds of CPU). <strong>Gigabytes of binary traffic flow directly from the client to cloud storage.</strong></p><hr><h2 id="_4-erasure-coding-the-math-of-11-nines-durability" tabindex="-1">4. Erasure Coding: The Math of &quot;11 Nines&quot; Durability <a class="header-anchor" href="#_4-erasure-coding-the-math-of-11-nines-durability" aria-label="Permalink to &quot;4. Erasure Coding: The Math of &quot;11 Nines&quot; Durability&quot;">​</a></h2><p>How do cloud providers (AWS S3) guarantee <strong>99.999999999% durability</strong> without tripling infrastructure costs?</p><p>Traditional <strong>3x Replication</strong> stores 3 identical copies of every file, consuming <strong>200% storage overhead</strong>:</p>',5)),a(o,null,{default:n(()=>[a(s,{code:"graph%20LR%0A%20%20%20%20subgraph%20Rep%20%5B%223x%20Replication%20(200%25%20Storage%20Overhead)%22%5D%0A%20%20%20%20%20%20%20%20F1%5B%223GB%20File%22%5D%20--%3E%20R1%5B%22Copy%201%20(3GB)%22%5D%0A%20%20%20%20%20%20%20%20F1%20--%3E%20R2%5B%22Copy%202%20(3GB)%22%5D%0A%20%20%20%20%20%20%20%20F1%20--%3E%20R3%5B%22Copy%203%20(3GB)%22%5D%0A%20%20%20%20%20%20%20%20Note1%5B%22Total%20Stored%3A%209GB%20(Expensive!)%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Erasure%20%5B%22Reed-Solomon%20Erasure%20Coding%20(8%2B4%3A%2050%25%20Overhead)%22%5D%0A%20%20%20%20%20%20%20%20F2%5B%223GB%20File%22%5D%20--%3E%20D%5B%22Split%20into%208%20Data%20Chunks%20(375MB%20each)%22%5D%0A%20%20%20%20%20%20%20%20D%20--%3E%20P%5B%22Compute%204%20Parity%20Chunks%20via%20Matrix%20Math%22%5D%0A%20%20%20%20%20%20%20%20Note2%5B%22Total%20Stored%3A%204.5GB%5CnCan%20lose%20ANY%204%20disks%20simultaneously%20without%20data%20loss!%22%5D%0A%20%20%20%20end%0A%0A%20%20%20%20classDef%20default%20fill%3A%231e293b%2Cstroke%3A%233b82f6%2Cstroke-width%3A1.5px%2Ccolor%3A%23f8fafc%3B%0A%20%20%20%20classDef%20success%20fill%3A%23064e3b%2Cstroke%3A%2310b981%2Cstroke-width%3A2px%2Ccolor%3A%23a7f3d0%3B%0A%20%20%20%20class%20Erasure%20success%3B%0A"})]),_:1}),e[8]||(e[8]=i(`<p>Under <strong>Reed-Solomon (8+4) Erasure Coding</strong>, a file is divided into 8 data fragments and transformed into 4 parity fragments distributed across 12 independent server racks.</p><p>Any 8 fragments can mathematically reconstruct the entire file. You can suffer a catastrophic hardware failure of <strong>4 complete server racks simultaneously with zero data loss</strong>, all while requiring only <strong>50% extra storage</strong> instead of 200%.</p><hr><h2 id="_5-content-addressable-storage-cas-deduplication" tabindex="-1">5. Content-Addressable Storage (CAS) &amp; Deduplication <a class="header-anchor" href="#_5-content-addressable-storage-cas-deduplication" aria-label="Permalink to &quot;5. Content-Addressable Storage (CAS) &amp; Deduplication&quot;">​</a></h2><p>In modern enterprise architectures, objects are named by their cryptographic hash:</p><p>$$\\text{Object Key} = \\text{SHA-256}(\\text{File Payload})$$</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s3://bucket/blobs/e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>If 10,000 employees in an enterprise attach the same 50MB PDF to an email, the system computes the hash, discovers the object already exists in CAS storage, and creates a metadata pointer. <strong>499.95 GB of disk storage is saved instantly.</strong></p><hr><h2 id="_6-architect-level-trade-offs" tabindex="-1">6. Architect-Level Trade-Offs <a class="header-anchor" href="#_6-architect-level-trade-offs" aria-label="Permalink to &quot;6. Architect-Level Trade-Offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Storage Architecture</th><th>Durability</th><th>Storage Overhead</th><th>Compute Cost</th></tr></thead><tbody><tr><td><strong>Direct Application Ingest</strong></td><td>Poor (vulnerable to server OOM)</td><td>0%</td><td>Massive CPU &amp; RAM hog on web servers.</td></tr><tr><td><strong>Presigned S3 Direct Upload</strong></td><td>Absolute (offloaded to cloud storage)</td><td>0% app overhead</td><td>Requires multipart coordination state.</td></tr><tr><td><strong>3x Replication</strong></td><td>High</td><td>200% extra disk</td><td>Zero CPU overhead (simple file copy).</td></tr><tr><td><strong>Reed-Solomon Erasure Coding</strong></td><td>Extreme (&quot;11 Nines&quot;)</td><td>30%–50% extra disk</td><td>CPU cost for parity matrix computation on write/rebuild.</td></tr></tbody></table><hr><h2 id="_7-mental-model-summary" tabindex="-1">7. Mental-Model Summary <a class="header-anchor" href="#_7-mental-model-summary" aria-label="Permalink to &quot;7. Mental-Model Summary&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Large binary files are physical payloads, not database records.</span></span>
<span class="line"><span>Slice them into checksummed chunks, upload them directly to storage via presigned URLs,</span></span>
<span class="line"><span>and protect durability with erasure coding rather than naive replication.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><strong>Rule 1</strong>: Never buffer large uploads in application server RAM; stream directly to object storage via presigned URLs.</li><li><strong>Rule 2</strong>: Enforce multipart chunking with client-side checksums (<code>Content-MD5</code>) for any file larger than 100MB.</li></ul><hr><h2 id="_8-the-next-battlefield" tabindex="-1">8. The Next Battlefield <a class="header-anchor" href="#_8-the-next-battlefield" aria-label="Permalink to &quot;8. The Next Battlefield&quot;">​</a></h2><p><em>We now store and assemble multi-gigabyte binary files reliably.</em></p><p><em>Now change the requirement: the user cannot wait 10 minutes to download a 4GB movie file before pressing play.</em></p><p><em>A user taps &#39;Play&#39; on a 4K movie stream. They demand playback startup in under 800 milliseconds, zero buffering, and seamless visual fidelity even as their phone switches from high-speed home fiber to cellular data in an elevator.</em></p><p><em>How do HLS, DASH, and Adaptive Bitrate (ABR) encoding transcode and slice video into dynamic edge streams?</em></p><p>👉 <strong>Next: <a href="/systems-beyond-the-code/book/part-04-media-search-edge/chapter-23-video-audio-streaming-architecture.html">Chapter 23 — The Spinning Wheel: Video &amp; Audio Streaming Architecture</a></strong></p>`,22))])}const k=d(h,[["render",u]]);export{C as __pageData,k as default};
